package com.ecommerce.auth.service; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="users",indexes=@Index(name="idx_user_email",columnList="email",unique=true)) public class User { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false,unique=true) String email; @Column(nullable=false) String passwordHash; @Column(nullable=false) String role="CUSTOMER"; boolean enabled=true; public UUID getId(){return id;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public boolean isEnabled(){return enabled;} }